def transform(grid):
    # Extend each diagonal colored run in the direction established by its paired cells.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    for color in {v for row in grid for v in row if v != background}:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Only diagonal pairs of this color define continuations; preserve all given cells.
        paired = set()
        for r, c in pts:
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    paired.add(((r, c), (nr, nc)))
        for (r, c), (nr, nc) in paired:
            dr, dc = nr - r, nc - c
            # Ignore pairs that belong to an unrelated crossing streak: a ray is
            # extended only when its own line contains no other non-background colors.
            for sr, sc, step_r, step_c in ((r, c, -dr, -dc), (nr, nc, dr, dc)):
                rr, cc = sr + step_r, sc + step_c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                    out[rr][cc] = color
                    rr += step_r
                    cc += step_c
    return out
